graphql.query:
query BuildingCountEntities {
    buildingCountEntities {
        items {
            id
            year
            buildingCount
            region {
                code
                name
                regionType {
                    id
                    name
                }
            }
            areaType {
                id
                name
            }
            buildingType {
                id
                name
            }
            shorelineType {
                id
                name
            }
            createdAt
            updatedAt
        }
        totalCount
        limit
        offset
        hasNextPage
    }
}

query BuildingCountEntities {
